<?php
 namespace QQWorld\Setup\Module\I18n\Parser\Adapter; class Xml extends AbstractAdapter { protected function _parse() { foreach ($this->_getNodes($this->_file) as $element) { if (!$element instanceof \SimpleXMLElement) { continue; } $attributes = $element->attributes(); if ((string)$attributes['translate'] === 'true' || (string)$attributes['translatable'] === 'true') { $this->_addPhrase((string)$element); } else { $this->parseTranslatableNodes($attributes, $element); } } } protected function _getNodes($file) { libxml_use_internal_errors(true); $xml = simplexml_load_file($file); libxml_use_internal_errors(false); if ($xml) { $nodes = $xml->xpath('//*[@translate|@translatable]'); unset($xml); return is_array($nodes) ? $nodes : []; } return []; } private function parseTranslatableNodes(\SimpleXMLElement $attributes, \SimpleXMLElement $element) { $nodesDelimiter = strpos($attributes['translate'], ' ') === false ? ',' : ' '; foreach (explode($nodesDelimiter, $attributes['translate']) as $value) { $phrase = (string)$element->{$value}; if ($phrase) { $this->_addPhrase($phrase); } $elementAttributes = $element->attributes(); if (isset($elementAttributes[$value])) { $phrase = (string)$elementAttributes[$value]; if ($phrase) { $this->_addPhrase($phrase); } } } } } 